"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Was entbrummt wird: der Take oder eine daraus gemachte Datei, die weder entbrummt noch hochskaliert ist.",
"Strength": "Stärke",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Wie viel der Frame-Welligkeit herausgeteilt wird. Viktors Gehör: 100 % machte den Anfang dünn, 80 % war richtig.",
"Which file is measured: the take, or any file made from it.": "Welche Datei gemessen wird: der Take oder jede daraus gemachte Datei.",
"Inspect": "Untersuchen",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Wo der Klang sitzt: Spektrogramm, mittleres Spektrum, Bandenergie. Leg einen anderen Take darüber, um zu vergleichen.",
"Log": "Log",
"Linear": "Linear",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Legt ein zweites Spektrum unter dieses, im selben Maßstab: eine aus diesem Take gemachte Datei oder einen anderen Take.",
"Compare with": "Vergleichen mit",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "Vollbild: zoomen und scrollen (oder Doppelklick auf das Bild). Ein Klick spielt von dort ab, wenn dieser Take im Player ist.",
"Full screen: zoom and scroll": "Vollbild: zoomen und scrollen",
"Whisper listens to this take on Forge and matches what it hears to your lyrics, minute by minute.": "Whisper hört diesen Take auf Forge und gleicht, was es hört, Minute für Minute mit deinem Liedtext ab.",
"What Whisper listens to": "Was Whisper hört",
"The take as it is, or a stem of it: on the vocal stem Whisper hears the words without the music": "Der Take, wie er ist, oder ein Stem davon: auf dem Gesangs-Stem hört Whisper die Worte ohne die Musik",
"Listen with Whisper": "Mit Whisper anhören",
