"Export format": "Exportformat",
"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC: verlustfrei, etwa halb so groß wie WAV. WAV: für Werkzeuge, die nichts anderes nehmen.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Auch jede aus jedem Take gemachte Datei (Remasters, Stems, Upscales, entbrummte Dateien), nach dem Take benannt.",
