"The server log, in every room: click to unfold or fold": "Das Server-Protokoll, in jedem Raum: klicken zum Auf- oder Einklappen",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "Die Leitung zum Studio: der Hin- und Rückweg, der Median der letzten fünf (alle 20 s). Nah: das Studio antwortet sofort.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Folgen: das Protokoll bleibt bei seiner neuesten Zeile, während die Engine schreibt. Aus: es bleibt, wo du zum Lesen hingescrollt hast.",
