"Finds takes here by title or library name: * stands for any letters, ? for one. The column's filters still apply.": "Findet Takes hier nach Titel oder Bibliotheksnamen: * steht für beliebige Buchstaben, ? für einen. Die Filter der Spalte gelten weiter.",
