"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ Ein Name im Stil ist eine Bitte, kein Versprechen. Was ▶ A und ▶ B spielen, ist, was YuE2 dafür gibt, etwa neun von zehn Mal. Manche Proben sind großartig, A und B stimmen überein, und doch ist das Instrument nicht das gewünschte: trau dem Ohr, nicht dem Namen.",
