"Drawing artwork for “{0}”: a prompt from its style and words, then the picture (about half a minute)": "Bild für „{0}“ wird gezeichnet: ein Prompt aus seinem Stil und seinen Worten, dann das Bild (etwa eine halbe Minute)",
