"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Wie breit die Änderung des Adapters ist: 16 für eine Stimme oder ein Instrument, 32 für einen Stil, 64 für viele Stimmen, höchstens 128.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Ob die Musikhälfte lernt (der Teil, der die Tokens des Songs schreibt) und wie stark ihre Lektion gegen den Anker zieht: 0 lässt sie wie die Basis, nur eine Klangfarbe; erhöhe es für Aussprache und Stil. Es zählt der Anteil des Ankers daran, nicht seine Größe.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Zieht die Musikhälfte zum Basismodell zurück, damit sie behält, was das Set nicht zeigt. Lies es als Anteil des AR-Gewichts: ein Zehntel lässt sie sich bewegen, so viel wie das Gewicht hält sie nah an der Basis. Nichts bei AR-Gewicht 0.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Die Lernrate der Musikhälfte als Anteil der obigen: der Regler, der sie schneller oder langsamer lernen lässt (0.5: halb so schnell). Ein kleines Set lernt sie schnell auswendig.",
"How they work ›": "Wie sie wirken ›",
"The music half's three knobs: the guide": "Die drei Regler der Musikhälfte: die Anleitung",
