"As the studio made it (and the Refiner finished it), no DAW in between.": "So, wie das Studio sie gemacht (und der Veredler sie fertiggestellt) hat, ohne DAW dazwischen.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "So, wie das Studio sie gemacht (und der Veredler sie fertiggestellt) hat, ohne DAW dazwischen. Der Take in der Hand:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Öffne einen Take, spiel einen ab oder hake einen im Bibliothekar an: sein WAV, FLAC und MP3 erscheinen hier.",
