"experimental": "experimentell",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Es funktioniert und wurde geprüft, braucht aber noch Belastungstests auf anderen Rechnern und Projekten und mehr Arbeit",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "Der ganze Take als Projekt deiner DAW: die Stems auf ihren Spuren, die Partitur als MIDI, das Tempo, die Abschnitte als Regionen, der Liedtext auf der Zeitleiste. Welche DAW nutzt du?",
