"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(der Mix, jeder Stem, die Partitur als Noten, die Abschnitte als Marker: Waveform 14, Bitwig, Studio One, Cubase); beides auch im Menü eines Takes → Herunterladen. Waveform: 14 oder neuer.",
"Packing…": "Wird gepackt…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 Tage Testphase mit allen Funktionen, dann eine Lizenz: 60 $ für den privaten Gebrauch oder ein kleines Unternehmen",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 oder neuer: kostenlos, ohne Spur- oder Exportgrenzen; öffnet das DAWproject des Studios (File > Import Other > Import a DAWproject file). Waveform 13 wird nicht unterstützt",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 Tage ohne Grenzen nach der Anmeldung, dann Essentials 99 $, Producer 199 $ oder Studio 399 $ (bitwig.com, 03.10.2026); öffnet das DAWproject des Studios: der Mix, die Stems, die Partitur als Noten, die Abschnitte als Marker",
