"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} auf der Musikhälfte liegt über seiner Grenze {2}: die Partitur scheitert meist nach 70-200 Tokens.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} auf der Klanghälfte liegt über seiner Grenze {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} plant Instrumentalpartituren: bei {1} mit zu singenden Worten verliert die Partitur ihre Gesangslinie (gemessen bei 1.00: 1 Note in 127 Gesangstakten, die Musik in Schleife). Halte es niedrig, 0.3–0.5, für einen gesungenen Song.",
