"The current official decoder, and the default. The cleanest, best-sounding one: start here.": "Der aktuelle offizielle Decoder und der Standard. Der sauberste, am besten klingende: fang hier an.",
"The older official decoder. The published benchmark scores were made with it. Less clean than Standard; some hear it as more musical. Same encoder, only the decoder differs.": "Der ältere offizielle Decoder. Die veröffentlichten Benchmark-Werte wurden mit ihm gemacht. Weniger sauber als Standard; manche hören ihn als musikalischer. Gleicher Encoder, nur der Decoder unterscheidet sich.",
"A community weight mix of the two official decoders: 2/3 Standard + 1/3 Legacy. Not newly trained. It sits between the clean Standard and the more musical Legacy; the real-audio LoRA's authors suggest it.": "Eine Gewichtsmischung der Community aus den beiden offiziellen Decodern: 2/3 Standard + 1/3 Legacy. Nicht neu trainiert. Er liegt zwischen dem sauberen Standard und dem musikalischeren Legacy; die Autoren des Echt-Audio-LoRA empfehlen ihn.",
