"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni hört 120 s jedes Tracks und entwirft seinen Stil. Früher gehörte Entwürfe werden beiseitegelegt (styles.DATE.json); die Beschriftungen ändern sich erst, wenn du sie schreibst.",
"Listen": "Anhören",
"Listening to {0}": "{0} wird angehört",
"Write {#0} styles into the captions of {1}?": "{#0} Stile in die Beschriftungen von {1} schreiben?",
"Each first line becomes: {0} The lyrics stay.": "Jede erste Zeile wird: {0} Der Liedtext bleibt.",
"Write": "Schreiben",
"{#0} captions written": {"one": "{#0} Beschriftung geschrieben", "other": "{#0} Beschriftungen geschrieben"},
"drafts here by {0}": "Entwürfe hier von {0}",
"The studio’s trainer is missing {0}:": "Dem Trainer des Studios fehlt {0}:",
"Comfy-Org's YuE2 {0} weights": "die YuE2-{0}-Gewichte von Comfy-Org",
"the realaudio tokenizer head": "der Kopf des realaudio-Tokenizers",
"and": "und",
"AI-Toolkit is not found at": "AI-Toolkit nicht gefunden unter",
": clone ostris/ai-toolkit there (or set AITK_ROOT for the lab), or train with the studio’s own trainer.": ": klone ostris/ai-toolkit dorthin (oder setze AITK_ROOT für das Labor) oder trainiere mit dem Trainer des Studios.",
"The realaudio tokenizer is missing from": "Der realaudio-Tokenizer fehlt in",
"{#0} characters, about {#1} tokens.": "{#0} Zeichen, etwa {#1} Tokens.",
"Style and lyrics together: about {#0} of {#1} tokens.": "Stil und Liedtext zusammen: etwa {#0} von {#1} Tokens.",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Stil und Liedtext zusammen: etwa {#0} von {#1} Tokens — zu lang für einen ganzen Song mit Partitur.",
"Unlike the model's training styles:": "Anders als die Trainingsstile des Modells:",
"longer than 1,600 characters (the official examples stop at 999)": "länger als 1.600 Zeichen (die offiziellen Beispiele enden bei 999)",
"{#0} Unicode arrow (→): write -> instead": "{#0} Unicode-Pfeil (→): schreib stattdessen ->",
"{#0} Unicode arrows (→): write -> instead": "{#0} Unicode-Pfeile (→): schreib stattdessen ->",
"dynamics marks (never in the official styles)": "Dynamikzeichen (nie in den offiziellen Stilen)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{#0} „Label:“-Felder (5 der 110 offiziellen Stile nutzen welche)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} Klammerzeile im Liedtext mit einem „Label:“, einem Pfeil oder einem p/f-Zeichen (keine in den offiziellen Beispielen)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} Klammerzeilen im Liedtext mit einem „Label:“, einem Pfeil oder einem p/f-Zeichen (keine in den offiziellen Beispielen)",
"{#0} instruments": {"one": "{#0} Instrument", "other": "{#0} Instrumente"},
"{#0} heard": "gehört: {#0}",
"{#0} questioned": "angezweifelt: {#0}",
"{#0} not identified": "nicht erkannt: {#0}",
"{#0} not judged yet": "noch nicht beurteilt: {#0}",
"the Librarian does not answer: no probes to play": "der Bibliothekar antwortet nicht: keine Proben zum Abspielen",
"{#0} styles": {"one": "{#0} Stil", "other": "{#0} Stile"},
"{#0} style": {"one": "{#0} Stil", "other": "{#0} Stile"},
"what a probe gave instead of its instrument": "was eine Probe statt ihres Instruments ergab",
"Nothing matches.": "Nichts passt.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Ein Name im Stil ist eine Bitte, kein Versprechen. Was ▶ A und ▶ B spielen, ist das, was YuE2 dafür gibt, etwa neun von zehn Mal.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Manche Proben sind großartig, und A und B stimmen überein, doch das Instrument ist nicht das gewünschte: vertrau dem Ohr, nicht dem Namen.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Was YuE2 spielen sollte, ein Instrument oder ein Stil auf einmal, in Proben von zwei Minuten (eine Minute bei den ersten), je zwei Seeds, A und B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Ein Instrument prägt den Stil des ganzen Stücks: eins zu nennen verschiebt auch das Arrangement. Ein Knistern oder Papierrascheln wie auf einer abgenutzten Platte ist ein unglücklicher Seed: mach es mit einem anderen neu.",
