"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Die freigegebenen Sets des Studios, wie ihr Autor sie veröffentlicht hat. Jedes kommt als eigener Arbeitsbereich, gegen Löschen gesperrt: seine Takes als MP3 mit Covern, Titeln und Notizen. Nur was du anforderst, wird heruntergeladen.",
