"“{0}” is here already": "„{0}“ ist schon hier",
"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Wiederherstellen holt die auf Hugging Face veröffentlichte Kopie zurück: fehlende Takes kommen wieder, Titel und Notizen werden wieder die veröffentlichten, und was hinzugefügt wurde, verlässt den Arbeitsbereich (diese Takes bleiben in der Bibliothek; seine eigenen Abschnitte bleiben). Um deinen zu behalten, wie er ist: Abbrechen, deinen Arbeitsbereich umbenennen (das ⋯ neben seinem Namen, dann Umbenennen…) und erneut Holen: das Original kommt unter eigenem Namen daneben.",
"Restore the original": "Das Original wiederherstellen",
