"Freeze “{0}”?": "„{0}“ einfrieren?",
"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Seine Takes bleiben, wie sie sind: sie werden gehört und gelesen, nie geändert, verschoben oder weggeworfen, und sie verlassen Alle Arbeitsbereiche und die Suche (ein Take, der auch in einem nicht eingefrorenen Arbeitsbereich ist, bleibt dort). Der Arbeitsbereich wird grau; Auftauen in seinem ⋯-Menü bringt alles zurück.",
