"Drag a point up for a flare, down for a fade, along the song to move it; double-click to add one, double-click a point to take it out. The strength above is the top of the curve.": "Zieh einen Punkt nach oben für ein Aufleuchten, nach unten für ein Ausblenden, entlang des Songs zum Verschieben; Doppelklick fügt einen hinzu, Doppelklick auf einen Punkt nimmt ihn heraus. Die Stärke oben ist der Gipfel der Kurve.",
