"Make it 2K or 4K (its long side 2560 or 3840) with an upscaler from artwork/upscalers/ (ESRGAN, DAT, HAT, SPAN…): a run of its own": "In 2K oder 4K bringen (lange Seite 2560 oder 3840) mit einem Upscaler aus artwork/upscalers/ (ESRGAN, DAT, HAT, SPAN…): ein eigener Lauf",
