"pictures for your songs from a prompt of your own: square, wide and tall from one seed, painted by Krea 2 Muse or Qwen-Image": "Bilder für deine Songs aus einem eigenen Prompt: quadratisch, breit und hoch aus einem Seed, gemalt von Krea 2 Muse oder Qwen-Image",
