"All the sound strengths together. By ear (05.10.2026): two adapters at sound 1.0 each, 2.0 together, brought a heavy bass; 0.55 together sounded right. Green to 1, amber to 1.5, red past it. Drag it to move them all at once, each in proportion.": "Alle Klangstärken zusammen. Nach Gehör (05.10.2026): zwei Adapter mit Klang je 1.0, zusammen 2.0, brachten einen schweren Bass; 0.55 zusammen klang richtig. Grün bis 1, Bernstein bis 1.5, Rot darüber. Ziehen, um alle auf einmal zu verschieben, jeden im Verhältnis.",
