"Tick what to look for. A take is shown when it has all of the ticked (AND), any of them (OR) or none of them (NOR); the numbers count the takes of this place.": "Hake an, wonach gesucht wird. Ein Take erscheint, wenn er alles Angehakte hat (AND), eins davon (OR) oder nichts davon (NOR); die Zahlen zählen die Takes dieses Orts.",
