"the Artist's Qwen-Image painters: 2512 with Lightning's 8 steps (Apache-2.0: its parts from Qwen, the transformer as GGUF) and 2.1 (Qwen's research licence)": "die Qwen-Image-Maler des Malers: 2512 mit den 8 Schritten von Lightning (Apache-2.0: seine Teile von Qwen, der Transformer als GGUF) und 2.1 (Qwens Forschungslizenz)",
"the Artist's Qwen-Image painters": "die Qwen-Image-Maler des Malers",
"for a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "für eine 16-GB-Karte (unter 20 GB liest sein Text-Encoder den Prompt auf dem Prozessor: 17 GB RAM); eine halbe Minute pro Bild auf einer 3090; weniger, wenn ein Teil schon hier ist",
"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "Für eine 16-GB-Karte (unter 20 GB liest sein Text-Encoder den Prompt auf dem Prozessor: 17 GB RAM); eine halbe Minute pro Bild auf einer 3090; weniger, wenn ein Teil schon hier ist",
"For a card of 24 GB; less when some of it is here": "Für eine 24-GB-Karte; weniger, wenn ein Teil schon hier ist",
"Under Qwen's research licence: research and evaluation only, not for commercial use (a cover for a song that is sold is commercial use); a card of 24 GB, about two minutes a picture": "Unter Qwens Forschungslizenz: nur Forschung und Bewertung, keine kommerzielle Nutzung (ein Cover für einen verkauften Song ist kommerzielle Nutzung); eine 24-GB-Karte, etwa zwei Minuten pro Bild",
"LoRA trainer's base": "Basis des LoRA-Trainers",
"Comfy-Org/YuE2 for the Trainer, with Mothersuperior's tokenizer head and m-a-p's MERT-v2-FullSong (the set's latent cache hears with it)": "Comfy-Org/YuE2 für den Trainer, mit dem Tokenizer-Kopf von Mothersuperior und MERT-v2-FullSong von m-a-p (der Latent-Cache des Sets hört damit)",
"Trains on unquantized weights; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "Trainiert auf nicht quantisierten Gewichten; die 2,5 GB von MERT-v2-FullSong gehören dazu, weniger, wenn es schon hier ist",
"For a smaller card; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "Für eine kleinere Karte; die 2,5 GB von MERT-v2-FullSong gehören dazu, weniger, wenn es schon hier ist",
"The Artist paints with it.": "Der Maler malt damit.",
"The Artist offers it under Painter.": "Der Maler bietet es unter Maler an.",
"The Trainer starts from it.": "Der Trainer beginnt damit.",
"The engine lists it at its next start; Compute then offers it.": "Die Engine listet es bei ihrem nächsten Start; Rechnen bietet es dann an.",
