"A folder that is there already; {0} goes into it as «{1}». On the same disk it is renamed at once; on another it is copied, checked file by file, then the link is switched, and the old copy stays, renamed, for you to remove after a look.": "Ein Ordner, der schon da ist; {0} kommt als «{1}» hinein. Auf derselben Platte wird es sofort umbenannt; auf einer anderen wird es kopiert, Datei für Datei geprüft, dann wird der Link umgestellt, und die alte Kopie bleibt, umbenannt, damit du sie nach einem Blick entfernst.",
"A Windows path works too: D:\\Music is /mnt/d/Music.": "Ein Windows-Pfad geht auch: D:\\Music ist /mnt/d/Music.",
"{0} cannot move there": "{0} kann nicht dorthin",
"The same disk: the folder is renamed there at once, nothing is copied.": "Dieselbe Platte: der Ordner wird dort sofort umbenannt, nichts wird kopiert.",
"Another disk: {0} copied (free there: {1}), checked file by file, then the link switched. The old copy stays, renamed, until you remove it.": "Eine andere Platte: {0} kopiert (dort frei: {1}), Datei für Datei geprüft, dann der Link umgestellt. Die alte Kopie bleibt, umbenannt, bis du sie entfernst.",
