"The whole page's text smaller or larger (−2 to +4 pt): the layout stays; a lifted frame has its own on top": "Der ganze Text der Seite kleiner oder größer (−2 bis +4 pt): das Layout bleibt; ein abgelöster Rahmen hat seinen eigenen obendrauf",
