"Line numbers": "Zeilennummern",
"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "Die Nummern der Zeilen im Feld, wie ein Code-Editor sie zeigt (Alt+K markiert eine Zeile, Alt+J springt zur nächsten Marke)",
"Marks: {0}": "Marken: {0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "Markierte Zeilen: Alt+K markiert die Zeile des Cursors oder hebt die Marke auf, Alt+J springt zur nächsten, Alt+Shift+J zur vorigen, Alt+Shift+K löscht sie. Drücken, um zur nächsten zu gehen.",
"Press to go to the next one.": "Drücken, um zur nächsten zu gehen.",
"line {0}: {1}": "Zeile {0}: {1}",
"Tags not closed or astray: {0}": "Nicht geschlossene oder verirrte Tags: {0}",
"Round brackets to look at: {0}": "Runde Klammern zum Ansehen: {0}",
"Stress marks off a vowel: {0}": "Betonungszeichen neben keinem Vokal: {0}",
"Words with two stress marks: {0}": "Wörter mit zwei Betonungszeichen: {0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "Ein Betonungszeichen (U+0301) steht direkt nach dem Vokal, den es betont. Drücken, um zum nächsten zu gehen.",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "Ein Wort, zwei Betonungszeichen: gewollt oder ein Versehen? Drücken, um zum nächsten zu gehen.",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "{0} ist ein freistehender Akzent, nicht das Betonungszeichen (U+0301 nach dem Vokal)",
"at the line's start": "am Zeilenanfang",
"(before {0})": "(vor {0})",
"after a space": "nach einem Leerzeichen",
"a second mark on {0}": "ein zweites Zeichen auf {0}",
"on {0}, not a vowel": "auf {0}, keinem Vokal",
"after {0}": "nach {0}",
"two marks in {0}": "zwei Zeichen in {0}",
"Consonant beats: {0}": "Konsonanten-Schläge: {0}",
"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "Schläge, die kein Vokal trägt, mit den Silben im Balken jeder Zeile gezählt (heller gezeichnet): ein Wort ohne Vokal (с, в, к, з, й, ў) und ein Verschlusslaut, der in einem Wort gegen eine Affrikate schließt (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "Die Tasten des Texteditors, wie in mcedit:\nAlt+K  die Zeile des Cursors markieren (nochmal: Marke aufheben)\nAlt+J  die nächste Marke · Alt+Shift+J die vorige\nAlt+O  die Marken löschen (auch Alt+Shift+K)\nAlt+L  zu einer Zeile nach Nummer gehen\nStrg+Y  die Zeile löschen\nAlt+↑ Alt+↓  die Zeile oder die markierten Zeilen verschieben\n[ am Zeilenanfang, oder Strg+Leertaste  die Abschnitts-Tags\nStrg+F  im Feld suchen\nAlt+I  der Spickzettel der Instrumente und Stile\nStrg+Z  eine Änderung zurücknehmen",
"Already in the lyrics, line {0}: a song has one": "Schon im Text, Zeile {0}: ein Song hat einen",
"The lyrics number their verses: this is the next one": "Der Text nummeriert seine Strophen: das ist die nächste",
"{0} times in the 110 official examples": "{0}-mal in den 110 offiziellen Beispielen",
"{#0} times in the 110 official examples": {"one": "{#0}-mal in den 110 offiziellen Beispielen", "other": "{#0}-mal in den 110 offiziellen Beispielen"},
"already at line {0}": "schon in Zeile {0}",
"the next verse": "die nächste Strophe",
"↑ ↓ choose · Enter or Tab puts it in · Esc closes": "↑ ↓ wählen · Enter oder Tab fügt ein · Esc schließt",
"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "TEST: keines der 110 offiziellen Beispiele schreibt es, also singt YuE2 es vielleicht als Wörter oder übergeht es. Hör hin, bevor du es behältst.",
