"Male vocals in the Style: a click puts them there (in place of female ones); a click on the lit one takes their tag out": "Männlicher Gesang im Stil: ein Klick setzt ihn hinein (anstelle des weiblichen); ein Klick auf den leuchtenden nimmt seinen Tag heraus",
"Female vocals in the Style: a click puts them there (in place of male ones); a click on the lit one takes their tag out": "Weiblicher Gesang im Stil: ein Klick setzt ihn hinein (anstelle des männlichen); ein Klick auf den leuchtenden nimmt seinen Tag heraus",
"Clear the music seed: every run picks a random one again": "Den Musik-Seed leeren: jeder Lauf wählt wieder einen zufälligen",
"Clear the sound seed: every run picks a random one again": "Den Klang-Seed leeren: jeder Lauf wählt wieder einen zufälligen",
"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did\n{0}": "Den Klang dieses Takes mit diesem VAE neu rendern: er wurde gemacht, bevor Takes ihre Latents behielten, daher dauert es so lange wie sein Klang\n{0}",
"Decode this take again with this VAE: its own sound, another decoder, in seconds\n{0}": "Diesen Take mit diesem VAE erneut dekodieren: sein eigener Klang, ein anderer Decoder, in Sekunden\n{0}",
"Play this version\n{0}": "Diese Version abspielen\n{0}",
"This version\n{0}": "Diese Version\n{0}",
"Sound seed {#0}\nsame music, another grain": "Klang-Seed {#0}\ndieselbe Musik, anderes Korn",
"None on this server. Start it with --sliders to add voice and genre sliders.": "Keine auf diesem Server. Starte ihn mit --sliders, um Stimm- und Genre-Regler hinzuzufügen.",
"{#0} decoders · {1} picked in the ☰ menu · a finished song can add another from its page": "{#0} Decoder · {1} im ☰-Menü gewählt · ein fertiger Song kann auf seiner Seite einen weiteren hinzufügen",
