"Between the sections a vocalise an octave up, written into the lyrics as «(Ooh, aah)», instead of a bar's rest": "Zwischen den Abschnitten eine Vokalise eine Oktave höher, im Text als «(Ooh, aah)» geschrieben, statt einer Takt-Pause",
"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "Den Take in der Hand aus dem Studio: die gemischte Spur, wie sie ist, oder den ganzen Take in deine DAW (mit seinen Stems, sobald sie hier getrennt sind)",
