"Not in OpenRouter's list: check the name": "Nicht in der Liste von OpenRouter: prüfe den Namen",
"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "Jedes Modell von openrouter.ai/models, geschrieben Anbieter/Modell; das Feld bietet beim Tippen die ganze Liste an, jedes mit seinem Preis pro Million Tokens rein und raus. Die Schnellwahl füllt es aus.",
