"none yet · load a model in the chat server": "noch keins · lade ein Modell im Chat-Server",
"Your draft is ready. Review and edit it, then apply what you like.": "Dein Entwurf ist fertig. Sieh ihn durch und bearbeite ihn, dann übernimm, was dir gefällt.",
"Export all": "Alles exportieren",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "Alles exportieren: jedes Dokument des Schreibers, mit seinen Versionen, den daraus gemachten Takes und seinem Papierkorb, in einer Datei (ein Backup)",
"Import a backup": "Ein Backup importieren",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "Ein Backup des Schreibers importieren: was hier fehlt, kommt dazu; Gleiches bleibt unberührt; ein Dokument, das von seinem Namensvetter hier abweicht, kommt als Kopie daneben. Hier wird nichts überschrieben",
"A Writer backup to import": "Ein Backup des Schreibers zum Importieren",
"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "Die Dokumentenspalte: ziehen zum Verbreitern; ← → über die Tastatur; Pos1 oder ein Doppelklick für ihre eigene Breite",
"Writer backup: {0} documents and {1} in the trash, into {2}": "Backup des Schreibers: {0} Dokumente und {1} im Papierkorb, nach {2}",
"not a Writer backup (a file this room exported)": "kein Backup des Schreibers (eine Datei, die dieser Raum exportiert hat)",
"Writer backup {0}: {1} new, {2} already here, {3} beside their namesakes as copies, {4} into the trash": "Backup des Schreibers {0}: {1} neu, {2} schon hier, {3} als Kopien neben ihren Namensvettern, {4} in den Papierkorb",
"Not imported: {0}": "Nicht importiert: {0}",
"Wipe out the art's trash": "Den Papierkorb der Bilder leeren",
