"Delete for good: {0} ({#1} MB).": "Endgültig löschen: {0} ({#1} MB).",
"This cannot be undone.\n\nThe covers of a frozen workspace's takes stay.": "Das lässt sich nicht rückgängig machen.\n\nDie Cover der Takes eines eingefrorenen Arbeitsbereichs bleiben.",
