"Filter: {#0} on, joined {1}": "Filter: {#0} aktiv, verbunden mit {1}",
"Filter the takes shown: tick what to look for, and whether a take needs all of it (AND), any of it (OR) or none of it (NOR)": "Die gezeigten Takes filtern: hake an, wonach gesucht wird, und ob ein Take alles davon braucht (AND), irgendetwas davon (OR) oder nichts davon (NOR)",
"Clear the choice": "Die Auswahl leeren",
"The choice": "Die Auswahl",
"To the trash: it gives them back until it is emptied": "In den Papierkorb: er gibt sie zurück, bis er geleert wird",
"With what is made from them: also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Mit dem, was daraus gemacht ist: auch jede Datei, die aus jedem Take gemacht wurde (Remaster, Stems, Hochskalierungen, entsummte Dateien), nach dem Take benannt.",
"Export ZIP: made on Forge, then saved by the browser where you tell it": "ZIP exportieren: auf Forge erstellt, dann vom Browser dort gespeichert, wo du es sagst",
