"A mark of the score. Each section of the lyrics with its words: the take's menu, Find the sections by ear": "Eine Marke der Partitur. Jeder Abschnitt des Textes mit seinen Wörtern: das Menü des Takes, Die Abschnitte nach Gehör finden",
