"it goes onto the clipboard and, where you say, into the Style prompt; a name the Style holds already is marked; a lyrics tag goes onto the clipboard only": "es geht in die Zwischenablage und, wo du es sagst, in den Stil-Prompt; ein Name, den der Stil schon enthält, wird markiert; ein Text-Tag geht nur in die Zwischenablage",
"The clipboard did not take it": "Die Zwischenablage hat es nicht angenommen",
"Russian · conservative (Viktor's)": "Russisch · konservativ (von Viktor)",
"The Artist's log": "Das Protokoll des Malers",
"Transcribed {0} in {1}. Check the melody under Supply your own score, then write the new lyrics and style.": "{0} in {1} transkribiert. Prüfe die Melodie unter Eigene Partitur liefern, dann schreib den neuen Text und den Stil.",
"1 take carries a score you can remix.": "1 Take trägt eine Partitur, die du remixen kannst.",
"{#0} takes carry a score you can remix.": {"one": "{#0} Take trägt eine Partitur, die du remixen kannst.", "other": "{#0} Takes tragen eine Partitur, die du remixen kannst."},
"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "Mach zuerst einen Song im Modus Voller Plan oder Nur Melodie; der Direkt-Modus behält keine Partitur.",
"A reference is a PNG, JPEG or WebP picture": "Eine Referenz ist ein PNG-, JPEG- oder WebP-Bild",
"The picture could not be read": "Das Bild ließ sich nicht lesen",
"Pick a take on the right first": "Wähle zuerst rechts einen Take",
"The prompt its artwork was drawn from": "Der Prompt, aus dem sein Artwork gezeichnet wurde",
"A prompt from its title and style: say more of what you see": "Ein Prompt aus seinem Titel und Stil: sag mehr von dem, was du siehst",
"Put the take's prompt in place of the one written here?": "Den Prompt des Takes an die Stelle des hier geschriebenen setzen?",
"What is written now goes; each run below keeps its own prompt.": "Was jetzt geschrieben steht, geht; jeder Lauf unten behält seinen eigenen Prompt.",
"Put it in": "Einsetzen",
"Pick a take with a cover on the right first": "Wähle zuerst rechts einen Take mit Cover",
