"A wedding band of brass in odd meters, loud and fast.": "Eine Hochzeits-Blaskapelle in ungeraden Takten, laut und schnell.",
"Andalusian guitar, handclaps and the Phrygian cadence.": "Andalusische Gitarre, Händeklatschen und die phrygische Kadenz.",
"Lisbon's song of longing, on the Portuguese guitar.": "Lissabons Lied der Sehnsucht, auf der portugiesischen Gitarre.",
"Buenos Aires: the bandoneon's breath and a dramatic step.": "Buenos Aires: der Atem des Bandoneons und ein dramatischer Schritt.",
"Rio's quiet samba: nylon strings and a soft sway.": "Rios leiser Samba: Nylonsaiten und sanftes Wiegen.",
"Lagos: horns over interlocking polyrhythms.": "Lagos: Bläser über verzahnten Polyrhythmen.",
"The oud and the qanun in an ornamented Eastern mode.": "Die Oud und die Kanun in einem verzierten östlichen Modus.",
"The santur's hammered strings in a contemplative mode.": "Die geschlagenen Saiten der Santur in einem besinnlichen Modus.",
"Ottoman salon music: the ney's breath over strings.": "Osmanische Salonmusik: der Atem der Ney über Saiten.",
"The duduk over its drone (the engine's own duduk, no adapter).": "Die Duduk über ihrem Bordun (die Duduk der Engine selbst, ohne Adapter).",
