"✦ Suggest": "✦ Vorschlagen",
"Style suggestions: the Writer's model reads the Style, the Title and the lyrics' first lines and offers short tags this song has not got yet; a click on one puts it in (before the BPM at its end)": "Stil-Vorschläge: das Modell des Schreibers liest den Stil, den Titel und die ersten Zeilen des Textes und bietet kurze Tags an, die dieser Song noch nicht hat; ein Klick auf einen setzt ihn ein (vor die BPM am Ende)",
