"Its strength over the steps: keyframes of a multiplier at a share of the steps, as ComfyUI's LoRA hooks. «0%:1, 50%:1, 60%:0» keeps it whole for half the steps and lets it go by 60 %; «0%:0, 30%:1» brings it in after the start. Between keyframes the multiplier runs straight; two at one share make a step.": "Seine Stärke über die Schritte: Keyframes eines Multiplikators bei einem Anteil der Schritte, wie ComfyUIs LoRA-Hooks. «0%:1, 50%:1, 60%:0» hält ihn die Hälfte der Schritte ganz und lässt ihn bis 60 % los; «0%:0, 30%:1» holt ihn nach dem Anfang herein. Zwischen Keyframes läuft der Multiplikator gerade; zwei beim selben Anteil ergeben eine Stufe.",
"Its strength over the steps": "Seine Stärke über die Schritte",
"Its keyframes": "Seine Keyframes",
"Not a keyframe: «{0}». Keyframes as «0%:1, 50%:1, 60%:0»: a share of the steps and a multiplier from 0 to 2, eight at most": "Kein Keyframe: «{0}». Keyframes wie «0%:1, 50%:1, 60%:0»: ein Anteil der Schritte und ein Multiplikator von 0 bis 2, höchstens acht",
