"Spectrum over the wave": "Spektrum über der Welle",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "Spektrum über der Welle: der Zeiger auf der Welle holt das Spektrogramm des ganzen Takes über den Player, so breit wie die Welle, darüber die Worte des Abschnitts. Klicken zum Ausschalten.",
"The take's spectrum": "Das Spektrum des Takes",
"spectral centroid": "spektraler Schwerpunkt",
"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "Der spektrale Schwerpunkt: wo das Gewicht des Klangs in jedem Moment liegt, seine Helligkeit; höher ist heller",
"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS: wie laut jeder Moment ist, in dBFS, im Streifen unten; die gestrichelte Linie ist der eigene Durchschnitt des Takes",
"Frequency scale": "Frequenzskala",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "Die Frequenzen auf einer logarithmischen Skala, wie das Ohr sie hört: jede Oktave so hoch wie die nächste",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "Die Frequenzen auf einer linearen Skala: die Höhen breit, die Tiefen unten zusammengedrängt",
"The mean power of each band over the whole take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k": "Die mittlere Leistung jedes Bandes über den ganzen Take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k",
