"its painter said nothing for {#0} s: stopped": "sein Maler sagte {#0} s lang nichts: gestoppt",
"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "Ein zweiter Durchgang, wie ihn Viktors ComfyUI-Workflow macht: das Bild 1.5- oder 2-fach vergrößert und von seinem eigenen Maler, seinen Adaptern, seinem Prompt und Seed übermalt, mit den Schritten und dem Sampler des Formulars; ein eigener Lauf",
"Second pass…": "Zweiter Durchgang…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "Wie sehr der zweite Durchgang das Bild ändern darf: 0.3 behält die Zeichnung und fügt Details hinzu, 0.5 schärft die Textur, 0.7 malt die Formen neu",
"Second pass asked:": "Zweiter Durchgang angefragt:",
"The second pass ×{0} waits for a card with room, then paints the picture over": "Der zweite Durchgang ×{0} wartet auf eine Karte mit Platz und übermalt dann das Bild",
"No second pass: {0}": "Kein zweiter Durchgang: {0}",
"second pass ×{0}": "zweiter Durchgang ×{0}",
"Extra noise": "Zusätzliches Rauschen",
"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "Frisches Rauschen auf dem Bild, bevor von ihm aus gemalt wird, wie Viktors ComfyUI-Workflow es tut (InjectLatentNoise): 0 keines, 0.3 neues Korn und Details, 0.6 sein zweiter Durchgang, über 1 beginnen die Formen des Bildes zu zerfallen",
"extra noise {0}": "zusätzliches Rauschen {0}",
"Regions": "Regionen",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Krea 2 and Qwen-Image 2512": "Bis zu drei Teile des Bildausschnitts, jeder mit eigenen Wörtern: bei jedem Schritt wird der Maler für jede Region noch einmal gefragt, mit dem Prompt und den Wörtern der Region, und die Antworten werden über Rahmen mit weichem Rand gemischt (wie bei Latent Couple). Jede Region kostet einen ganzen Durchgang mehr pro Schritt. Krea 2 und Qwen-Image 2512",
